17	import (
18		"fmt"
19		"slices"
20		"strings"
21	)
22	
23	type adjacency map[string][]string
24	
25	type importGraph struct {
26		nodes map[string]struct{}
27		edges adjacency
28	}
29	
30	func (i *importGraph) addNode(name string) {
31		if i.nodes == nil {
32			i.nodes = make(map[string]struct{})
33		}
34		if _, exists := i.nodes[name]; exists {
35			return
36		}
37		i.nodes[name] = struct{}{}
38	}
39	
40	func (i *importGraph) addNodes(names []string) {
41		for _, name := range names {
42			i.addNode(name)
43		}
44	}
45	
46	func (i *importGraph) removeNode(name string) {
47		delete(i.nodes, name)
48	}
49	
50	func (i *importGraph) removeNodes(names []string) {
51		for _, name := range names {
52			i.removeNode(name)
53		}
54	}
55	
56	func (i *importGraph) addEdge(from, to string) error {
57		if !i.exists(from) || !i.exists(to) {
58			return fmt.Errorf("one of the nodes does not exist")
59		}
60	
61		// A cycle is formed if `to` can already reach `from`; adding the edge
62		// would close the loop. Surface the full chain of files involved so the
63		// caller can diagnose the cycle rather than its depth.
64		if cycle := i.findPath(to, from); cycle != nil {
65			return fmt.Errorf("import cycle detected: %s", strings.Join(append(cycle, to), " -> "))
66		}
67	
68		if i.areConnected(from, to) {
69			// if connected, there's nothing to do
70			return nil
71		}
72	
73		if i.nodes == nil {
74			i.nodes = make(map[string]struct{})
75		}
76		if i.edges == nil {
77			i.edges = make(adjacency)
78		}
79	
80		i.edges[from] = append(i.edges[from], to)
81		return nil
82	}
83	
84	func (i *importGraph) addEdges(from string, tos []string) error {
85		for _, to := range tos {
86			err := i.addEdge(from, to)
87			if err != nil {
88				return err
89			}
90		}
91		return nil
92	}
93	
94	func (i *importGraph) areConnected(from, to string) bool {
95		al, ok := i.edges[from]
96		if !ok {
97			return false
98		}
99		return slices.Contains(al, to)
100	}
101	
102	// findPath searches for any path through the graph from start to target,
103	// returning the chain of node names (including both ends). It returns nil
104	// when the two nodes are not connected. Edge traversal order follows edge
105	// insertion order so the reported chain is stable across repeated runs.
106	func (i *importGraph) findPath(start, target string) []string {
107		if start == target {
108			return []string{start}
109		}
110	
111		parent := map[string]string{start: ""}
112		queue := []string{start}
113	
114		for len(queue) > 0 {
115			current := queue[0]
116			queue = queue[1:]
117	
118			for _, next := range i.edges[current] {
119				if _, visited := parent[next]; visited {
120					continue
121				}
122				parent[next] = current
123				if next == target {
124					// reconstruct the chain from target back to start
125					chain := []string{target}
126					for node := target; parent[node] != ""; node = parent[node] {
127						chain = append(chain, parent[node])
128					}
129					slices.Reverse(chain)
130					return chain
131				}
132				queue = append(queue, next)
133			}
134		}
135	
136		return nil
137	}
138	
139	func (i *importGraph) exists(key string) bool {
140		_, exists := i.nodes[key]
141		return exists
142	}
