14	
15	package caddyfile
16	
17	import (
18		"bytes"
19		"fmt"
20		"io"
21		"os"
22		"path/filepath"
23		"slices"
24		"strings"
25	
26		"go.uber.org/zap"
27	
28		"github.com/caddyserver/caddy/v2"
29	)
30	
31	// Parse parses the input just enough to group tokens, in
32	// order, by server block. No further parsing is performed.
33	// Server blocks are returned in the order in which they appear.
34	// Directives that do not appear in validDirectives will cause
35	// an error. If you do not want to check for valid directives,
36	// pass in nil instead.
37	//
38	// Environment variables in {$ENVIRONMENT_VARIABLE} notation
39	// will be replaced before parsing begins.
40	func Parse(filename string, input []byte) ([]ServerBlock, error) {
41		// unfortunately, we must copy the input because parsing must
42		// remain a read-only operation, but we have to expand environment
43		// variables before we parse, which changes the underlying array (#4422)
44		inputCopy := make([]byte, len(input))
45		copy(inputCopy, input)
46	
47		tokens, err := allTokens(filename, inputCopy)
48		if err != nil {
49			return nil, err
50		}
51		p := parser{
52			Dispenser: NewDispenser(tokens),
53			importGraph: importGraph{
54				nodes: make(map[string]struct{}),
55				edges: make(adjacency),
56			},
57		}
58		return p.parseAll()
59	}
60	
61	// allTokens lexes the entire input, but does not parse it.
62	// It returns all the tokens from the input, unstructured
63	// and in order. It may mutate input as it expands env vars.
64	func allTokens(filename string, input []byte) ([]Token, error) {
65		return Tokenize(replaceEnvVars(input), filename)
66	}
67	
68	// replaceEnvVars replaces all occurrences of environment variables.
69	// It mutates the underlying array and returns the updated slice.
70	func replaceEnvVars(input []byte) []byte {
71		var offset int
72		for {
73			begin := bytes.Index(input[offset:], spanOpen)
74			if begin < 0 {
75				break
76			}
77			begin += offset // make beginning relative to input, not offset
78			end := bytes.Index(input[begin+len(spanOpen):], spanClose)
79			if end < 0 {
80				break
81			}
82			end += begin + len(spanOpen) // make end relative to input, not begin
83	
84			// get the name; if there is no name, skip it
85			envString := input[begin+len(spanOpen) : end]
86			if len(envString) == 0 {
87				offset = end + len(spanClose)
88				continue
89			}
90	
91			// split the string into a key and an optional default
92			envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
93	
94			// do a lookup for the env var, replace with the default if not found
95			envVarValue, found := os.LookupEnv(envParts[0])
96			if !found && len(envParts) == 2 {
97				envVarValue = envParts[1]
98			}
99	
100			// get the value of the environment variable
101			// note that this causes one-level deep chaining
102			envVarBytes := []byte(envVarValue)
103	
104			// splice in the value
105			input = append(input[:begin],
106				append(envVarBytes, input[end+len(spanClose):]...)...)
107	
108			// continue at the end of the replacement
109			offset = begin + len(envVarBytes)
110		}
111		return input
112	}
113	
114	type parser struct {
115		*Dispenser
116		block           ServerBlock // current server block being parsed
117		eof             bool        // if we encounter a valid EOF in a hard place
118		definedSnippets map[string][]Token
119		nesting         int
120		importGraph     importGraph
121		// realPathCache memoizes canonical (symlink-resolved) paths of
122		// lexical file paths; see parser.realPath.
123		realPathCache map[string]string
124	}
125	
126	func (p *parser) parseAll() ([]ServerBlock, error) {
127		var blocks []ServerBlock
128	
129		for p.Next() {
130			err := p.parseOne()
131			if err != nil {
132				return blocks, err
133			}
134			if len(p.block.Keys) > 0 || len(p.block.Segments) > 0 {
135				blocks = append(blocks, p.block)
136			}
137			if p.nesting > 0 {
138				return blocks, p.EOFErr()
139			}
140		}
141	
142		return blocks, nil
143	}
144	
145	func (p *parser) parseOne() error {
146		p.block = ServerBlock{}
147		return p.begin()
148	}
149	
150	func (p *parser) begin() error {
151		if len(p.tokens) == 0 {
152			return nil
153		}
154	
155		err := p.addresses()
156		if err != nil {
157			return err
158		}
159	
160		if p.eof {
161			// this happens if the Caddyfile consists of only
162			// a line of addresses and nothing else
163			return nil
164		}
165	
166		if ok, name := p.isNamedRoute(); ok {
167			// we just need a dummy leading token to ease parsing later
168			nameToken := p.Token()
169			nameToken.Text = name
170	
171			// named routes only have one key, the route name
172			p.block.Keys = []Token{nameToken}
173			p.block.IsNamedRoute = true
174	
175			// get all the tokens from the block, including the braces
176			tokens, err := p.blockTokens(true)
177			if err != nil {
178				return err
179			}
180			tokens = append([]Token{nameToken}, tokens...)
181			p.block.Segments = []Segment{tokens}
182			return nil
183		}
184	
185		if ok, name := p.isSnippet(); ok {
186			if p.definedSnippets == nil {
187				p.definedSnippets = map[string][]Token{}
188			}
189			if _, found := p.definedSnippets[name]; found {
190				return p.Errf("redeclaration of previously declared snippet %s", name)
191			}
192			// consume all tokens til matched close brace
193			tokens, err := p.blockTokens(false)
194			if err != nil {
195				return err
196			}
197			// Just as we need to track which file the token comes from, we need to
198			// keep track of which snippet the token comes from. This is helpful
199			// in tracking import cycles across files/snippets by namespacing them.
200			// Without this, we end up with false-positives in cycle-detection.
201			for k, v := range tokens {
202				v.snippetName = name
203				tokens[k] = v
204			}
205			p.definedSnippets[name] = tokens
206			// empty block keys so we don't save this block as a real server.
207			p.block.Keys = nil
208			return nil
209		}
210	
211		return p.blockContents()
212	}
213	
214	func (p *parser) addresses() error {
215		var expectingAnother bool
216	
217		for {
218			value := p.Val()
219			token := p.Token()
220	
221			// Reject request matchers if trying to define them globally
222			if strings.HasPrefix(value, "@") {
223				return p.Errf("request matchers may not be defined globally, they must be in a site block; found %s", value)
224			}
225	
226			// Special case: import directive replaces tokens during parse-time
227			if value == "import" && p.isNewLine() {
228				err := p.doImport(0)
229				if err != nil {
230					return err
231				}
232				continue
233			}
234	
235			// Open brace definitely indicates end of addresses
236			if value == "{" {
237				if expectingAnother {
238					return p.Errf("Expected another address but had '%s' - check for extra comma", value)
239				}
240				// Mark this server block as being defined with braces.
241				// This is used to provide a better error message when
242				// the user may have tried to define two server blocks
243				// without having used braces, which are required in
244				// that case.
245				p.block.HasBraces = true
246				break
247			}
248	
249			// Users commonly forget to place a space between the address and the '{'
250			if strings.HasSuffix(value, "{") {
251				return p.Errf("Site addresses cannot end with a curly brace: '%s' - put a space between the token and the brace", value)
252			}
253	
254			if value != "" { // empty token possible if user typed ""
255				// Trailing comma indicates another address will follow, which
256				// may possibly be on the next line
257				if value[len(value)-1] == ',' {
258					value = value[:len(value)-1]
259					expectingAnother = true
260				} else {
261					expectingAnother = false // but we may still see another one on this line
262				}
263	
264				// If there's a comma here, it's probably because they didn't use a space
265				// between their two domains, e.g. "foo.com,bar.com", which would not be
266				// parsed as two separate site addresses.
267				if strings.Contains(value, ",") {
268					return p.Errf("Site addresses cannot contain a comma ',': '%s' - put a space after the comma to separate site addresses", value)
269				}
270	
271				// After the above, a comma surrounded by spaces would result
272				// in an empty token which we should ignore
273				if value != "" {
274					// Add the token as a site address
275					token.Text = value
276					p.block.Keys = append(p.block.Keys, token)
277				}
278			}
279	
280			// Advance token and possibly break out of loop or return error
281			hasNext := p.Next()
282			if expectingAnother && !hasNext {
283				return p.EOFErr()
284			}
285			if !hasNext {
286				p.eof = true
287				break // EOF
288			}
289			if !expectingAnother && p.isNewLine() {
290				break
291			}
292		}
293	
294		return nil
295	}
296	
297	func (p *parser) blockContents() error {
298		errOpenCurlyBrace := p.openCurlyBrace()
299		if errOpenCurlyBrace != nil {
300			// single-server configs don't need curly braces
301			p.cursor--
302		}
303	
304		err := p.directives()
305		if err != nil {
306			return err
307		}
308	
309		// only look for close curly brace if there was an opening
310		if errOpenCurlyBrace == nil {
311			err = p.closeCurlyBrace()
312			if err != nil {
313				return err
314			}
315		}
316	
317		return nil
318	}
319	
320	// directives parses through all the lines for directives
321	// and it expects the next token to be the first
322	// directive. It goes until EOF or closing curly brace
323	// which ends the server block.
324	func (p *parser) directives() error {
325		for p.Next() {
326			// end of server block
327			if p.Val() == "}" {
328				// p.nesting has already been decremented
329				break
330			}
331	
332			// special case: import directive replaces tokens during parse-time
333			if p.Val() == "import" {
334				err := p.doImport(1)
335				if err != nil {
336					return err
337				}
338				p.cursor-- // cursor is advanced when we continue, so roll back one more
339				continue
340			}
341	
342			// normal case: parse a directive as a new segment
343			// (a "segment" is a line which starts with a directive
344			// and which ends at the end of the line or at the end of
345			// the block that is opened at the end of the line)
346			if err := p.directive(); err != nil {
347				return err
348			}
349		}
350	
351		return nil
352	}
353	
354	// doImport swaps out the import directive and its argument
355	// (a total of 2 tokens) with the tokens in the specified file
356	// or globbing pattern. When the function returns, the cursor
357	// is on the token before where the import directive was. In
358	// other words, call Next() to access the first token that was
359	// imported.
360	func (p *parser) doImport(nesting int) error {
361		// syntax checks
362		if !p.NextArg() {
363			return p.ArgErr()
364		}
365		importPattern := p.Val()
366		if importPattern == "" {
367			return p.Err("Import requires a non-empty filepath")
368		}
369	
370		// grab remaining args as placeholder replacements
371		args := p.RemainingArgs()
372	
373		// set up a replacer for non-variadic args replacement
374		repl := makeArgsReplacer(args)
375	
376		// grab all the tokens (if it exists) from within a block that follows the import
377		var blockTokens []Token
378		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
379			blockTokens = append(blockTokens, p.Token())
380		}
381		// initialize with size 1
382		blockMapping := make(map[string][]Token, 1)
383		if len(blockTokens) > 0 {
384			// use such tokens to create a new dispenser, and then use it to parse each block
385			bd := NewDispenser(blockTokens)
386	
387			// one iteration processes one sub-block inside the import
388			for bd.Next() {
389				currentMappingKey := bd.Val()
390	
391				if currentMappingKey == "{" {
392					return p.Err("anonymous blocks are not supported")
393				}
394	
395				// load up all arguments (if there even are any)
396				currentMappingTokens := bd.RemainingArgsAsTokens()
397	
398				// load up the entire block
399				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
400					currentMappingTokens = append(currentMappingTokens, bd.Token())
401				}
402	
403				blockMapping[currentMappingKey] = currentMappingTokens
404			}
405		}
406	
407		// splice out the import directive and its arguments
408		// (2 tokens, plus the length of args)
409		tokensBefore := p.tokens[:p.cursor-1-len(args)-len(blockTokens)]
410		tokensAfter := p.tokens[p.cursor+1:]
411		var importedTokens []Token
412		var nodes []string
413	
414		// first check snippets. That is a simple, non-recursive replacement
415		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
416			importedTokens = p.definedSnippets[importPattern]
417			if len(importedTokens) > 0 {
418				// just grab the first one
419				nodes = append(nodes, p.fileNodeName(importedTokens[0].File, importedTokens[0].snippetName))
420			}
421		} else {
422			// expand file imports (and globs) into tokens; nodes are the
423			// canonical file identities so the import graph tracks the same
424			// real file regardless of how it was addressed
425			fileTokens, fileNodes, err := p.resolveFileImports(importPattern)
426			if err != nil {
427				return err
428			}
429			importedTokens = fileTokens
430			nodes = fileNodes
431		}
432	
433		nodeName := p.graphNodeName()
434		p.importGraph.addNode(nodeName)
435		p.importGraph.addNodes(nodes)
436		if err := p.importGraph.addEdges(nodeName, nodes); err != nil {
437			p.importGraph.removeNodes(nodes)
438			// surface the offending import site along with the cycle chain so
439			// the error is diagnosable even when the loop closes through an
440			// alias that resolves to the current file
441			return p.Errf("%v (while importing %s)", err, importPattern)
442		}
443	
444		// copy the tokens so we don't overwrite p.definedSnippets
445		tokensCopy := make([]Token, 0, len(importedTokens))
446	
447		var (
448			maybeSnippet   bool
449			maybeSnippetId bool
450			index          int
451		)
452	
453		// run the argument replacer on the tokens
454		// golang for range slice return a copy of value
455		// similarly, append also copy value
456		for i, token := range importedTokens {
457			// update the token's imports to refer to import directive filename, line number and snippet name if there is one
458			if token.snippetName != "" {
459				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName))
460			} else {
461				token.imports = append(token.imports, fmt.Sprintf("%s:%d (import)", p.File(), p.Line()))
462			}
463	
464			// naive way of determine snippets, as snippets definition can only follow name + block
465			// format, won't check for nesting correctness or any other error, that's what parser does.
466			if !maybeSnippet && nesting == 0 {
467				// first of the line
468				if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
469					index = 0
470				} else {
471					index++
472				}
473	
474				if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
475					maybeSnippetId = true
476				}
477			}
478	
479			switch token.Text {
480			case "{":
481				nesting++
482				if index == 1 && maybeSnippetId && nesting == 1 {
483					maybeSnippet = true
484					maybeSnippetId = false
485				}
486			case "}":
487				nesting--
488				if nesting == 0 && maybeSnippet {
489					maybeSnippet = false
490				}
491			}
492			// if it is {block}, we substitute with all tokens in the block
493			// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
494			var tokensToAdd []Token
495			foundBlockDirective := false
496			switch {
497			case token.Text == "{block}":
498				foundBlockDirective = true
499				tokensToAdd = blockTokens
500			case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
501				foundBlockDirective = true
502				// {blocks.foo.bar} will be extracted to key `foo.bar`
503				blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
504				val, ok := blockMapping[blockKey]
505				if ok {
506					tokensToAdd = val
507				}
508			}
509	
510			if foundBlockDirective {
511				if maybeSnippet {
512					tokensCopy = append(tokensCopy, token)
513				} else {
514					tokensCopy = append(tokensCopy, tokensToAdd...)
515				}
516				continue
517			}
518	
519			if maybeSnippet {
520				tokensCopy = append(tokensCopy, token)
521				continue
522			}
523	
524			foundVariadic, startIndex, endIndex := parseVariadic(token, len(args))
525			if foundVariadic {
526				for _, arg := range args[startIndex:endIndex] {
527					token.Text = arg
528					tokensCopy = append(tokensCopy, token)
529				}
530			} else {
531				token.Text = repl.ReplaceKnown(token.Text, "")
532				tokensCopy = append(tokensCopy, token)
533			}
534		}
535	
536		// splice the imported tokens in the place of the import statement
537		// and rewind cursor so Next() will land on first imported token
538		p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
539		p.cursor -= len(args) + len(blockTokens) + 1
540	
541		return nil
542	}
543	
544	// graphNodeName returns the import-graph node for the file currently
545	// being processed. The file part is its canonical identity (see
546	// realPath) so cycles are tracked by real file, and snippet tokens are
547	// namespaced by snippet name so importing a snippet remains distinct
548	// from importing its file.
549	func (p *parser) graphNodeName() string {
550		return p.fileNodeName(p.File(), p.Token().snippetName)
551	}
552	
553	// fileNodeName builds the canonical graph node for a file, optionally
554	// namespaced by snippet name.
555	func (p *parser) fileNodeName(file, snippet string) string {
556		name := file
557		if real, err := p.realPath(file); err == nil {
558			name = real
559		}
560		if snippet != "" {
561			name += fmt.Sprintf(":%s", snippet)
562		}
563		return name
564	}
565	
566	// resolveFileImports expands an import pattern (a concrete path or a
567	// glob) into the imported tokens. It also returns the canonical
568	// identities of the imported files, for import-cycle tracking.
569	//
570	// Canonical identities are symlink-resolved, absolute, cleaned paths, so
571	// the same physical file reached by different spellings (symlink
572	// aliases, ".." segments, or a mix of absolute and relative paths) is
573	// treated as one file. The lexical path is still used to open the file;
574	// once read, its tokens are anchored to the canonical path, so a file
575	// reached through a symlink resolves its own relative imports against
576	// the file that declares them.
577	//
578	// Within a single glob, a file matched more than once (for example both
579	// a real file and a symlink to it) expands only once, in a deterministic
580	// order based on the canonical path. Explicitly repeated imports are
581	// different statements and keep their own semantics.
582	func (p *parser) resolveFileImports(importPattern string) ([]Token, []string, error) {
583		// make path relative to the file of the _token_ being processed rather
584		// than current working directory (issue #867) and then use glob to get
585		// list of matching filenames
586		absFile, err := caddy.FastAbs(p.Dispenser.File())
587		if err != nil {
588			return nil, nil, p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
589		}
590	
591		var globPattern string
592		if !filepath.IsAbs(importPattern) {
593			globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
594		} else {
595			globPattern = importPattern
596		}
597		if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
598			(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
599			// See issue #2096 - a pattern with many glob expansions can hang for too long
600			return nil, nil, p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
601		}
602		matches, err := filepath.Glob(globPattern)
603		if err != nil {
604			return nil, nil, p.Errf("Failed to use import pattern %s: %v", importPattern, err)
605		}
606		if len(matches) == 0 {
607			if strings.ContainsAny(globPattern, "*?[]") {
608				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
609				return nil, nil, nil
610			}
611			return nil, nil, p.Errf("File to import not found: %s", importPattern)
612		}
613	
614		// See issue #5295 - should skip any files that start with a . when iterating over them.
615		sep := string(filepath.Separator)
616		segGlobPattern := strings.Split(globPattern, sep)
617		if strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
618			var tmpMatches []string
619			for _, m := range matches {
620				seg := strings.Split(m, sep)
621				if !strings.HasPrefix(seg[len(seg)-1], ".") {
622					tmpMatches = append(tmpMatches, m)
623				}
624			}
625			matches = tmpMatches
626		}
627	
628		// A single glob statement may address the same real file more than
629		// once (a file and a symlink alias, two aliases, or equivalent
630		// spellings). Resolve each lexical match to its canonical identity,
631		// drop duplicates, and sort by canonical path so the expansion order
632		// is stable and independent of how the pattern was written or the
633		// order the filesystem returned entries in.
634		type resolvedImport struct {
635			lexical string // path used to read the file and anchor its relative imports
636			real    string // canonical identity used for dedup and cycle tracking
637		}
638		resolved := make([]resolvedImport, 0, len(matches))
639		seen := make(map[string]struct{}, len(matches))
640		for _, match := range matches {
641			realPath, err := p.realPath(match)
642			if err != nil {
643				return nil, nil, p.Errf("Could not resolve import %s: %v", match, err)
644			}
645			if _, dup := seen[realPath]; dup {
646				continue
647			}
648			seen[realPath] = struct{}{}
649			resolved = append(resolved, resolvedImport{lexical: match, real: realPath})
650		}
651		slices.SortFunc(resolved, func(a, b resolvedImport) int {
652			return strings.Compare(a.real, b.real)
653		})
654	
655		var importedTokens []Token
656		nodes := make([]string, 0, len(resolved))
657		for _, imp := range resolved {
658			newTokens, err := p.doSingleImport(imp.lexical)
659			if err != nil {
660				return nil, nil, err
661			}
662			importedTokens = append(importedTokens, newTokens...)
663			nodes = append(nodes, imp.real)
664		}
665	
666		return importedTokens, nodes, nil
667	}
668	
669	// realPath returns the canonical identity of a file path: absolute,
670	// cleaned, and with symlinks resolved. It is used to recognize the same
671	// physical file across different spellings. Results are memoized for the
672	// duration of a parse so repeated adaptation over the same file tree is
673	// consistent and avoids redundant filesystem work.
674	//
675	// If a path cannot be fully evaluated (for example a dangling symlink),
676	// it falls back to the cleaned absolute path; the subsequent open in
677	// doSingleImport then reports the underlying I/O error using the
678	// existing error paths.
679	func (p *parser) realPath(path string) (string, error) {
680		if p.realPathCache == nil {
681			p.realPathCache = make(map[string]string)
682		}
683		if cached, ok := p.realPathCache[path]; ok {
684			return cached, nil
685		}
686	
687		abs, err := caddy.FastAbs(path)
688		if err != nil {
689			return "", err
690		}
691	
692		// Resolve symlinks to obtain the real file identity. If the path
693		// cannot be fully evaluated (a dangling symlink, a permission error,
694		// ...), fall back to the cleaned absolute path: the subsequent open
695		// in doSingleImport then reports the underlying I/O error using the
696		// existing error paths, so unreadable imports keep their established
697		// error categories.
698		real := abs
699		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
700			real = filepath.Clean(resolved)
701		}
702		if osPathCaseInsensitive {
703			real = strings.ToLower(real)
704		}
705	
706		p.realPathCache[path] = real
707		return real, nil
708	}
709	
710	// doSingleImport lexes the individual file at importFile and returns
711	// its tokens or an error, if any.
712	func (p *parser) doSingleImport(importFile string) ([]Token, error) {
713		file, err := os.Open(importFile)
714		if err != nil {
715			return nil, p.Errf("Could not import %s: %v", importFile, err)
716		}
717		defer file.Close()
718	
719		if info, err := file.Stat(); err != nil {
720			return nil, p.Errf("Could not import %s: %v", importFile, err)
721		} else if info.IsDir() {
722			return nil, p.Errf("Could not import %s: is a directory", importFile)
723		}
724	
725		input, err := io.ReadAll(file)
726		if err != nil {
727			return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
728		}
729	
730		// only warning in case of empty files
731		if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
732			caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
733			return []Token{}, nil
734		}
735	
736		importedTokens, err := allTokens(importFile, input)
737		if err != nil {
738			return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
739		}
740	
741		// Tack the file path onto these tokens so errors show the imported file's name
742		// (we use full, absolute path to avoid bugs: issue #1892). Use the canonical,
743		// symlink-resolved path: relative imports inside an imported file must resolve
744		// relative to the file that actually declares them, even when it was reached
745		// through a symlink alias or a path containing "..".
746		filename, err := p.realPath(importFile)
747		if err != nil {
748			return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
749		}
750		for i := range importedTokens {
751			importedTokens[i].File = filename
752		}
753	
754		return importedTokens, nil
755	}
756	
757	// directive collects tokens until the directive's scope
758	// closes (either end of line or end of curly brace block).
759	// It expects the currently-loaded token to be a directive
760	// (or } that ends a server block). The collected tokens
761	// are loaded into the current server block for later use
762	// by directive setup functions.
763	func (p *parser) directive() error {
764		// a segment is a list of tokens associated with this directive
765		var segment Segment
766	
767		// the directive itself is appended as a relevant token
768		segment = append(segment, p.Token())
769	
770		for p.Next() {
771			if p.Val() == "{" {
772				p.nesting++
773				if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
774					return p.Err("Unexpected next token after '{' on same line")
775				}
776				if p.isNewLine() {
777					return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
778				}
779			} else if p.Val() == "{}" {
780				if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
781					return p.Err("Unexpected '{}' at end of line")
782				}
783			} else if p.isNewLine() && p.nesting == 0 {
784				p.cursor-- // read too far
785				break
786			} else if p.Val() == "}" && p.nesting > 0 {
787				p.nesting--
788			} else if p.Val() == "}" && p.nesting == 0 {
789				return p.Err("Unexpected '}' because no matching opening brace")
790			} else if p.Val() == "import" && p.isNewLine() {
791				if err := p.doImport(1); err != nil {
792					return err
793				}
794				p.cursor-- // cursor is advanced when we continue, so roll back one more
795				continue
796			}
797	
798			segment = append(segment, p.Token())
799		}
800	
801		p.block.Segments = append(p.block.Segments, segment)
802	
803		if p.nesting > 0 {
804			return p.EOFErr()
805		}
806	
807		return nil
808	}
809	
810	// openCurlyBrace expects the current token to be an
811	// opening curly brace. This acts like an assertion
812	// because it returns an error if the token is not
813	// an opening curly brace. It does NOT advance the token.
814	func (p *parser) openCurlyBrace() error {
815		if p.Val() != "{" {
816			if p.valLooksLikeGlobalOptionsAfterImportedSnippets() {
817				return p.Err("global options block must appear before import directives; move the global options block to the top of the Caddyfile")
818			}
819			return p.SyntaxErr("{")
820		}
821		return nil
822	}
823	
824	func (p *parser) valLooksLikeGlobalOptionsAfterImportedSnippets() bool {
825		if p.Val() != "import" || len(p.block.Keys) == 0 {
826			return false
827		}
828	
829		for _, key := range p.block.Keys {
830			if !strings.HasPrefix(key.Text, "(") || !strings.HasSuffix(key.Text, ")") {
831				return false
832			}
833		}
834	
835		return true
836	}
837	
838	// closeCurlyBrace expects the current token to be
839	// a closing curly brace. This acts like an assertion
840	// because it returns an error if the token is not
841	// a closing curly brace. It does NOT advance the token.
842	func (p *parser) closeCurlyBrace() error {
843		if p.Val() != "}" {
844			return p.SyntaxErr("}")
845		}
846		return nil
847	}
848	
849	func (p *parser) isNamedRoute() (bool, string) {
850		keys := p.block.Keys
851		// A named route block is a single key with parens, prefixed with &.
852		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "&(") && strings.HasSuffix(keys[0].Text, ")") {
853			return true, strings.TrimSuffix(keys[0].Text[2:], ")")
854		}
855		return false, ""
856	}
857	
858	func (p *parser) isSnippet() (bool, string) {
859		keys := p.block.Keys
860		// A snippet block is a single key with parens. Nothing else qualifies.
861		if len(keys) == 1 && strings.HasPrefix(keys[0].Text, "(") && strings.HasSuffix(keys[0].Text, ")") {
862			return true, strings.TrimSuffix(keys[0].Text[1:], ")")
863		}
864		return false, ""
865	}
866	
867	// read and store everything in a block for later replay.
868	func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
869		// block must have curlies.
870		err := p.openCurlyBrace()
871		if err != nil {
872			return nil, err
873		}
874		nesting := 1 // count our own nesting
875		tokens := []Token{}
876		if retainCurlies {
877			tokens = append(tokens, p.Token())
878		}
879		for p.Next() {
880			if p.Val() == "}" {
881				nesting--
882				if nesting == 0 {
883					if retainCurlies {
884						tokens = append(tokens, p.Token())
885					}
886					break
887				}
888			}
889			if p.Val() == "{" {
890				nesting++
891			}
892			tokens = append(tokens, p.tokens[p.cursor])
893		}
894		// make sure we're matched up
895		if nesting != 0 {
896			return nil, p.SyntaxErr("}")
897		}
898		return tokens, nil
899	}
