901	// ServerBlock associates any number of keys from the
902	// head of the server block with tokens, which are
903	// grouped by segments.
904	type ServerBlock struct {
905		HasBraces    bool
906		Keys         []Token
907		Segments     []Segment
908		IsNamedRoute bool
909	}
910	
911	func (sb ServerBlock) GetKeysText() []string {
912		res := make([]string, 0, len(sb.Keys))
913		for _, k := range sb.Keys {
914			res = append(res, k.Text)
915		}
916		return res
917	}
