919	// DispenseDirective returns a dispenser that contains
920	// all the tokens in the server block.
921	func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
922		var tokens []Token
923		for _, seg := range sb.Segments {
924			if len(seg) > 0 && seg[0].Text == dir {
925				tokens = append(tokens, seg...)
926			}
927		}
928		return NewDispenser(tokens)
929	}
