931	// Segment is a list of tokens which begins with a directive
932	// and ends at the end of the directive (either at the end of
933	// the line, or at the end of a block it opens).
934	type Segment []Token
935	
936	// Directive returns the directive name for the segment.
937	// The directive name is the text of the first token.
938	func (s Segment) Directive() string {
939		if len(s) > 0 {
940			return s[0].Text
941		}
942		return ""
943	}
944	
945	// spanOpen and spanClose are used to bound spans that
946	// contain the name of an environment variable.
947	var (
948		spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
949		envVarDefaultDelimiter = ":"
950	)
951

