// canonicalCasePath rewrites each component of an absolute, symlink-resolved
// path to the spelling it actually has on disk.
//
// Whether two names differing only in case denote the same file is a property
// of the filesystem the path is mounted on, not of the operating system: a
// case-insensitive APFS, NTFS or FAT volume folds them, and a case-sensitive
// volume keeps them distinct. A literal component, when it exists, is always
// kept as-is; only when no entry with that exact spelling exists do we look up
// a case-insensitive match. As soon as a component cannot be found or read,
// the remaining components keep their lexical spelling, which is harmless
// because such paths fail later through the usual import error paths.
func canonicalCasePath(resolved string) string {
	vol := filepath.VolumeName(resolved)
	rest := strings.TrimPrefix(resolved[len(vol):], string(filepath.Separator))
	components := strings.Split(rest, string(filepath.Separator))

	current := vol
	if current == "" {
		current = string(filepath.Separator)
	}

	for i, comp := range components {
		if comp == "" || comp == "." || comp == ".." {
			current = filepath.Join(current, comp)
			continue
		}

		entries, err := os.ReadDir(current)
		if err != nil {
			// Cannot canonicalize from here on; keep the rest lexical.
			return filepath.Join(append([]string{current}, components[i:]...)...)
		}

		actual := comp
		caseInsensitiveMatch := ""
		for _, entry := range entries {
			name := entry.Name()
			if name == comp {
				// exact on-disk spelling: nothing to fold
				caseInsensitiveMatch = ""
				break
			}
			if caseInsensitiveMatch == "" && strings.EqualFold(name, comp) {
				caseInsensitiveMatch = name
			}
		}
		if caseInsensitiveMatch != "" {
			actual = caseInsensitiveMatch
		}
		current = filepath.Join(current, actual)
	}

